columnHelper.accessor('name', {
  header: 'Tool',
  cell: ({ row }) => (
    <div className="flex items-center gap-3">
      <ToolIcon
        url={row.original.icon_url || ''}
        category={row.original.owner_department}
      />
      <span>{row.original.name}</span>
    </div>
  ),
})

columnHelper.accessor('status', {
  header: 'Status',
  cell: ({ getValue }) => {
    const status = getValue()
    return (
      <span
        className={`px-3 py-1 text-white rounded-full text-sm capitalize bg-gradient-to-br ${statusStyles[status]}`}
      >
        {status}
      </span>
    )
  },
})

const ActionsCell = ({ row }: { row: any }) => {
  ...
  {(['view', 'edit', 'delete'] as const).map((act) => (
    <button
      key={act}
      onClick={() => {
        setAction({ mode: act, tool: row.original })
        setOpen(false)
      }}
      className={...}
    >
      {act === 'view' ? 'View' : act === 'edit' ? 'Edit' : 'Delete'}
    </button>
  ))}
}

columnHelper.display({
  id: 'actions',
  header: '',
  cell: ({ row }) => <ActionsCell row={row} />,
})

const { data: refToolsData, isLoading: toolsLoading } = useTools({
  ...params,
  name_like: query || undefined,
})
const tools = refToolsData || []
